package techguns.gametest;
import net.minecraft.gametest.framework.*;
import net.minecraft.core.BlockPos;
import net.minecraft.world.item.*;
import net.minecraft.world.level.material.Fluids;
import net.minecraftforge.common.capabilities.ForgeCapabilities;
import net.minecraftforge.fluids.*;
import net.minecraftforge.fluids.capability.IFluidHandler.FluidAction;
import net.minecraftforge.gametest.*;
import techguns.*;
import techguns.machines.*;
@GameTestHolder(Techguns.MODID) @PrefixGameTestTemplate(false)
public final class ChemicalGameTests {
    private static ProcessingMachine machine(GameTestHelper h){h.setBlock(1,1,1,TGMachines.BLOCKS.get(MachineKind.CHEM_LAB).get());return (ProcessingMachine)h.getBlockEntity(new BlockPos(1,1,1));}
    @GameTest(template="empty") public static void incendiaryAmmoConsumesSourceLavaAndReagentAmounts(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,new ItemStack(TGItems.PISTOL_ROUNDS.get(),2));m.inventory.setStackInSlot(1,new ItemStack(Items.BLAZE_POWDER));m.inputTank.fill(new FluidStack(Fluids.LAVA,250),FluidAction.EXECUTE);m.setEnergy(2500);m.tick();h.assertTrue(m.running()&&m.inputTank.isEmpty(),"Starting an incendiary recipe reserves its lava and item inputs");for(int i=0;i<100;i++)m.tick();h.assertTrue(m.inventory.getStackInSlot(3).is(TGItems.PISTOL_ROUNDS_INCENDIARY.get())&&m.inventory.getStackInSlot(3).getCount()==2&&m.energy.getEnergyStored()==0,"Original recipe produces two incendiary pistol rounds after 100 ticks and 2500 FE");h.succeed();}
    @GameTest(template="empty") public static void fluidOnlyAcidOutputSurvivesSaveAndReload(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,TGItems.BIOMASS.get().getDefaultInstance());m.inventory.setStackInSlot(1,new ItemStack(Items.GUNPOWDER));m.inputTank.fill(new FluidStack(Fluids.WATER,1000),FluidAction.EXECUTE);m.setEnergy(2000);m.tick();for(int i=0;i<40;i++)m.tick();h.assertTrue(m.running()&&m.pending().isEmpty(),"An operation can produce fluid without producing an item");var copy=new ProcessingMachine(m.getBlockPos(),m.getBlockState());copy.setLevel(h.getLevel());copy.load(m.saveWithoutMetadata());for(int i=40;i<100;i++)copy.tick();h.assertTrue(copy.outputTank.getFluid().getFluid()==TGFluids.ACID.get()&&copy.outputTank.getFluidAmount()==1000&&!copy.running(),"Pending acid output survives persistence and is produced once");h.succeed();}
    @GameTest(template="empty") public static void chemicalRecipeRejectsWrongFluidAndExtraBottle(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,TGItems.RIFLE_ROUNDS.get().getDefaultInstance());m.inventory.setStackInSlot(1,new ItemStack(Items.BLAZE_POWDER));m.inputTank.fill(new FluidStack(Fluids.WATER,250),FluidAction.EXECUTE);m.tick();h.assertFalse(m.running(),"Water cannot replace lava in incendiary ammunition");m.inputTank.setFluid(new FluidStack(Fluids.LAVA,250));m.inventory.setStackInSlot(2,new ItemStack(Items.GLASS_BOTTLE));m.tick();h.assertTrue(!m.running()&&m.inputTank.getFluidAmount()==250,"A recipe requiring an empty flask slot must reject an extra bottle without consuming fluid");h.succeed();}
    @GameTest(template="empty") public static void fullFluidOutputPausesWithoutLosingFinishedAcid(GameTestHelper h){var m=machine(h);m.inventory.setStackInSlot(0,TGItems.BIOMASS.get().getDefaultInstance());m.inventory.setStackInSlot(1,new ItemStack(Items.GUNPOWDER));m.inputTank.fill(new FluidStack(Fluids.WATER,1000),FluidAction.EXECUTE);m.setEnergy(2000);m.tick();m.outputTank.fill(new FluidStack(Fluids.WATER,16000),FluidAction.EXECUTE);for(int i=0;i<102;i++)m.tick();h.assertTrue(m.running()&&m.progress==100&&m.energy.getEnergyStored()==0,"Changed fluid output must retain the completed transaction without spending extra power");m.outputTank.setFluid(FluidStack.EMPTY);m.tick();h.assertTrue(!m.running()&&m.outputTank.getFluidAmount()==1000,"Clearing the output completes the saved acid operation");h.succeed();}
    @GameTest(template="empty") public static void fluidAutomationFillsInputAndSelectsDrainTank(GameTestHelper h){var m=machine(h);var fluids=m.getCapability(ForgeCapabilities.FLUID_HANDLER).orElseThrow(IllegalStateException::new);h.assertTrue(fluids.fill(new FluidStack(Fluids.LAVA,9000),FluidAction.EXECUTE)==8000,"The source input tank capacity is eight buckets");h.assertTrue(fluids.drain(1000,FluidAction.EXECUTE).isEmpty(),"The default drain route exposes output, never steals input");m.button(5);h.assertTrue(fluids.drain(1000,FluidAction.EXECUTE).getAmount()==1000&&m.inputTank.getFluidAmount()==7000,"The drain toggle exposes the input tank explicitly");m.button(3);h.assertTrue(m.inputTank.isEmpty(),"Input dump empties only input");h.succeed();}
}
